"module": "blackout", "source_id": "AFTD2022-EXP-05643c50d6cf5973", "guideline_quote": "Some drivers may attribute a crash or driving mishap to a ‘blackout’ to excuse an event that occurred for some other reason such as inattention or distraction (e.g. a mobile phone conversation).", "fact_fields": ["blackout.occurred"], "licence_pathway": "unconditional", "finding": "not_established", "conclusion": "The patient's blackout is diagnosed, so the unconditional standard does not apply."}, {
"module": "blackout", "source_id": "AFTD2022-BLK-COM-006", "guideline_quote": "Where a firm diagnosis has been made, the standard appropriate to the condition should be referred to in this publication (refer to Figure 6. Management of blackouts and driving).", "fact_fields": ["blackout.diagnosis"], "licence_pathway": "conditional", "finding": "established_restriction", "conclusion": "The patient's blackout is diagnosed, and the guidelines suggest applying the standard appropriate to the condition."}]}

